      "ru": "Отрегулируйте блочный тренажер так, чтобы подушечка для сгибаний проповедника находилась на уровне груди. Встаньте лицом к канатному тренажеру, поставив ноги на ширине плеч. Возьмите рукоятку троса обратным хватом снизу и прижмите плечо к подушечке для сгибаний проповедника. Держите спину прямо, а корпус напряженным. Медленно поверните рукоятку троса к плечу, прижимая плечо к подушке. Задержитесь на мгновение в верхней точке движения, напрягая бицепсы. Медленно опустите рукоятку троса обратно в исходное положение. Повторите необходимое количество повторений. Поменяйте руки и повторите упражнение."
